-- SOURCE supabase/schemas/seating/seating_plans/functions/private.normalize_seating_appearance.sql
CREATE OR REPLACE FUNCTION private.normalize_seating_appearance(p_target text, p_value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $function$
declare keys text[]; defaults jsonb; v jsonb; k text;
begin
 if p_value is null or jsonb_typeof(p_value)<>'object' then raise exception 'Invalid appearance' using errcode='22023'; end if;
 case p_target
 when 'room' then defaults:='{"floor_style":"neutral","table_theme":"generic"}';
 when 'table_theme' then defaults:='{"table_theme":"generic"}';
 when 'dance_floor' then defaults:='{"style":"classic_parquet"}';
 when 'stage','dj_booth' then defaults:='{}';
 else raise exception 'Invalid appearance target' using errcode='22023'; end case;
 if exists(select 1 from jsonb_object_keys(p_value) a where not(defaults ? a)) then raise exception 'Invalid appearance fields' using errcode='22023'; end if;
 v:=defaults||p_value;
 for k in select jsonb_object_keys(v) loop
   if jsonb_typeof(v->k)<>'string' then raise exception 'Invalid appearance value' using errcode='22023'; end if;
   case k
   when 'floor_style' then keys:=array['neutral','light_oak','dark_oak','marble','tiles','concrete'];
   when 'table_theme' then keys:=array['generic','classic_ivory','rustic_green','modern_white','elegant_gold'];
   when 'style' then keys:=array['classic_parquet','herringbone','dark_wood','white','black_white','minimal'];
   end case;
   if not((v->>k)=any(keys)) then raise exception 'Invalid appearance value' using errcode='22023'; end if;
 end loop;return v;
end
$function$;
ALTER FUNCTION private.normalize_seating_appearance(text, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.normalize_seating_appearance(text, jsonb) FROM PUBLIC, anon, authenticated, service_role;

-- SOURCE supabase/schemas/seating/seating_plans/functions/public.set_seating_appearance.sql
CREATE OR REPLACE FUNCTION public.set_seating_appearance(p_plan_id uuid, p_revision bigint, p_target text, p_object_id uuid, p_appearance jsonb, p_all boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $function$
declare v public.seating_plans; e public.seating_elements; normalized jsonb; plan_appearance jsonb; next_revision bigint;
begin
 v:=private.lock_seating_plan(p_plan_id,p_revision);
 if p_all is distinct from false then raise exception 'Invalid appearance target' using errcode='22023';end if;
 plan_appearance:=v.appearance;
 if p_target='room' and p_object_id is null then
  -- Validate the patch before merging: arrays/scalars must not silently replace an object.
  perform private.normalize_seating_appearance('room',p_appearance);
  plan_appearance:=private.normalize_seating_appearance('room',v.appearance||p_appearance);
 elsif p_target='table_theme' and p_object_id is null then
  normalized:=private.normalize_seating_appearance('table_theme',p_appearance);
  plan_appearance:=private.normalize_seating_appearance('room',v.appearance||normalized);
 elsif p_target='element' and p_object_id is not null then
  select * into e from public.seating_elements where id=p_object_id and plan_id=v.id and project_id=v.project_id;
  if not found then raise exception 'Element missing' using errcode='P0002';end if;
  normalized:=private.normalize_seating_appearance(e.kind,p_appearance);
  update public.seating_elements set appearance=normalized where id=e.id and plan_id=v.id;
 else raise exception 'Invalid appearance target' using errcode='22023';end if;
 -- One plan write/revision, irrespective of the number of existing or future tables.
 update public.seating_plans set appearance=plan_appearance,revision=revision+1,updated_at=now() where id=v.id returning revision into next_revision;
 return jsonb_build_object('revision',next_revision,'affected',1);
end
$function$;
ALTER FUNCTION public.set_seating_appearance(uuid, bigint, text, uuid, jsonb, boolean) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.set_seating_appearance(uuid, bigint, text, uuid, jsonb, boolean) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.set_seating_appearance(uuid, bigint, text, uuid, jsonb, boolean) TO authenticated;

-- SOURCE supabase/schemas/seating/seating_templates/functions/private.validate_seating_template.sql
CREATE OR REPLACE FUNCTION private.validate_seating_template(p_document jsonb, p_version integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item jsonb; v_width integer; v_height integer; v_x integer; v_y integer; v_w integer; v_h integer;
begin
 if (p_version is null or p_version<>2) or p_document is null or jsonb_typeof(p_document)<>'object' then raise exception 'Unsupported template document' using errcode='22023'; end if;
 if not(p_document ?& array['width_cm','height_cm','tables','elements','appearance']) or exists(select 1 from jsonb_object_keys(p_document) k where k not in ('width_cm','height_cm','tables','elements','appearance')) then raise exception 'Invalid template fields' using errcode='22023'; end if;
 if jsonb_typeof(p_document->'width_cm')<>'number' or jsonb_typeof(p_document->'height_cm')<>'number' or (p_document->>'width_cm') !~ '^[0-9]{1,6}$' or (p_document->>'height_cm') !~ '^[0-9]{1,6}$' or jsonb_typeof(p_document->'tables')<>'array' then raise exception 'Invalid template dimensions' using errcode='22023'; end if;
 if jsonb_typeof(p_document->'elements') is distinct from 'array' then raise exception 'Invalid template elements' using errcode='22023'; end if;
 if not private.seating_appearance_valid('room',p_document->'appearance') then raise exception 'Invalid room appearance' using errcode='22023';end if;
 v_width:=(p_document->>'width_cm')::integer;v_height:=(p_document->>'height_cm')::integer;
 if v_width not between 100 and 100000 or v_height not between 100 and 100000 or jsonb_array_length(p_document->'tables')>200 then raise exception 'Template limits exceeded' using errcode='22023'; end if;
 for v_item in select value from jsonb_array_elements(p_document->'tables') loop
 if jsonb_typeof(v_item)<>'object' then raise exception 'Invalid template table' using errcode='22023'; end if;
 if not(v_item ?& array['name','shape','capacity','x_cm','y_cm','width_cm','height_cm','rotation_deg']) or exists(select 1 from jsonb_object_keys(v_item) k where k not in ('name','shape','capacity','x_cm','y_cm','width_cm','height_cm','rotation_deg')) then raise exception 'Invalid table fields' using errcode='22023'; end if;
 if jsonb_typeof(v_item->'name')<>'string' or char_length(trim(v_item->>'name')) not between 1 and 150 or jsonb_typeof(v_item->'shape')<>'string' or (v_item->>'shape') not in ('round','rectangle') then raise exception 'Invalid table identity' using errcode='22023'; end if;
 if exists(select 1 from unnest(array['capacity','x_cm','y_cm','width_cm','height_cm','rotation_deg']) k where jsonb_typeof(v_item->k)<>'number' or (v_item->>k) !~ '^[0-9]{1,6}$') then raise exception 'Invalid table numbers' using errcode='22023'; end if;
 v_x:=(v_item->>'x_cm')::integer;v_y:=(v_item->>'y_cm')::integer;v_w:=(v_item->>'width_cm')::integer;v_h:=(v_item->>'height_cm')::integer;
 if (v_item->>'capacity')::integer not between 1 and 100 or (v_item->>'rotation_deg')::integer not between 0 and 359 or v_w not between 10 and 10000 or v_h not between 10 and 10000 or not private.seating_geometry_fits(v_item->>'shape',v_x,v_y,v_w,v_h,(v_item->>'rotation_deg')::integer,v_width,v_height) or ((v_item->>'shape')='round' and v_w<>v_h) then raise exception 'Invalid table geometry' using errcode='22023'; end if;
 end loop;
  if jsonb_array_length(p_document->'elements')>200 then raise exception 'Element limit exceeded' using errcode='22023'; end if;
  for v_item in select value from jsonb_array_elements(p_document->'elements') loop
   if not(v_item ? 'appearance') or not private.seating_element_valid(v_item,v_width,v_height) then raise exception 'Invalid element geometry' using errcode='22023'; end if;
  end loop;
end $function$
;
ALTER FUNCTION private.validate_seating_template(jsonb,integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.validate_seating_template(jsonb,integer) FROM PUBLIC, anon, authenticated, service_role;

-- SOURCE supabase/schemas/seating/seating_templates/functions/public.create_seating_plan_from_template.sql
CREATE OR REPLACE FUNCTION public.create_seating_plan_from_template(p_project_id uuid, p_template_id uuid, p_name text, p_rsvp_invitation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_template public.seating_templates;v_plan public.seating_plans;v_item jsonb;
begin
 perform private.lock_seating_project(p_project_id);
 select * into v_template from public.seating_templates where id=p_template_id and is_active for share;
 if not found then raise exception 'Active template missing' using errcode='P0002'; end if;
 perform private.validate_seating_template(v_template.document,v_template.document_version);
 insert into public.seating_plans(project_id,name,rsvp_invitation_id,width_cm,height_cm,appearance)
 values(p_project_id,trim(p_name),p_rsvp_invitation_id,(v_template.document->>'width_cm')::integer,(v_template.document->>'height_cm')::integer,private.normalize_seating_appearance('room',v_template.document->'appearance')) returning * into v_plan;
 for v_item in select value from jsonb_array_elements(v_template.document->'tables') loop
 insert into public.seating_tables(project_id,plan_id,name,shape,capacity,x_cm,y_cm,width_cm,height_cm,rotation_deg)
 values(p_project_id,v_plan.id,trim(v_item->>'name'),v_item->>'shape',(v_item->>'capacity')::integer,(v_item->>'x_cm')::integer,(v_item->>'y_cm')::integer,(v_item->>'width_cm')::integer,(v_item->>'height_cm')::integer,(v_item->>'rotation_deg')::integer);
 end loop;
 for v_item in select value from jsonb_array_elements(v_template.document->'elements') loop
 insert into public.seating_elements(project_id,plan_id,kind,name,x_cm,y_cm,width_cm,height_cm,rotation_deg,z_index,locked,appearance)
 values(p_project_id,v_plan.id,v_item->>'kind',trim(v_item->>'name'),(v_item->>'x_cm')::integer,(v_item->>'y_cm')::integer,(v_item->>'width_cm')::integer,(v_item->>'height_cm')::integer,(v_item->>'rotation_deg')::integer,(v_item->>'z_index')::integer,(v_item->>'locked')::boolean,private.normalize_seating_appearance(v_item->>'kind',v_item->'appearance'));
 end loop;
 return to_jsonb(v_plan);
end $function$
;
ALTER FUNCTION public.create_seating_plan_from_template(uuid,uuid,text,uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.create_seating_plan_from_template(uuid,uuid,text,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.create_seating_plan_from_template(uuid,uuid,text,uuid) TO authenticated;

-- Allow only the reviewed default/CHECK and PostgreSQL 18's own NOT NULL catalog entry.
-- No CASCADE: any unreviewed dependency aborts the whole transaction.
ALTER TABLE public.seating_tables DROP CONSTRAINT seating_tables_appearance_check;
ALTER TABLE public.seating_tables DROP COLUMN appearance RESTRICT;
